import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
css='''[hidden]{display:none!important}*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui;color:#18342d;background:#f4f7f4}header,main{max-width:1200px;margin:auto;padding:24px}header{padding-bottom:8px}h1{font-size:28px;margin:0 0 8px}h2{font-size:20px}p{max-width:900px}a{color:#175f68}nav{display:flex;gap:12px;flex-wrap:wrap}.pill,button,select{padding:8px 12px;border:1px solid #b5cbc3;background:white;border-radius:6px;font:inherit}.pill.active{background:#173f35;color:white}.notice{border-left:4px solid #c39326;background:#fff4d4;padding:12px 16px;margin:20px 0}.stats{display:flex;flex-wrap:wrap;gap:25px;background:white;padding:16px;border-radius:8px}.stats strong{display:block;font-size:23px}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.stage{height:610px;position:relative;background:#08211d;overflow:hidden;touch-action:none;border-radius:8px}.stage svg{width:100%;height:100%;display:block}.em-label{position:absolute;font-size:12px;line-height:1.2;background:#08211de8;color:white;padding:4px 6px;border-radius:4px;pointer-events:none;max-width:160px}.legend{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:12px 0;font-size:13px}.bar{width:240px;height:12px;background:linear-gradient(90deg,#0c2a48,#1d76aa,#3dd0b6,#ffc734,#ff4d23)}.scale{display:flex;width:240px;justify-content:space-between;font-size:11px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:white;padding:12px;border-radius:8px}.card img{width:100%}.card h3{margin:0 0 8px;font-size:16px}table{border-collapse:collapse;background:white;max-width:100%;font-size:13px}td,th{padding:8px 12px;text-align:left;border-bottom:1px solid #dce6df}code{overflow-wrap:anywhere;font-size:12px}details{margin-top:18px}footer{padding:24px;font-size:13px} @media(max-width:700px){.grid{grid-template-columns:1fr}.stage{height:480px}header,main{padding:16px}h1{font-size:24px}}'''
